import { DataWidget } from './DataWidget.js';
import { dayKey } from './storage.js';
export class CalendarWidget extends DataWidget {
  constructor(config,dashboard){super({...config,title:'Календарь',symbol:'▦'},dashboard);this.month=new Date();this.month.setDate(1);}
  update(){const title=this.month.toLocaleDateString('ru-RU',{month:'long',year:'numeric'});const header=this.element('div','calendar-month');header.append(this.actionButton('‹','previous','Предыдущий месяц'),this.element('strong','',title),this.actionButton('›','next','Следующий месяц'));const weekdays=this.element('div','calendar-weekdays');['Пн','Вт','Ср','Чт','Пт','Сб','Вс'].forEach(d=>weekdays.append(this.element('span','',d)));const grid=this.element('div','calendar-days');const offset=(this.month.getDay()+6)%7;const days=new Date(this.month.getFullYear(),this.month.getMonth()+1,0).getDate();for(let i=0;i<offset;i++)grid.append(this.element('span','blank-day'));for(let d=1;d<=days;d++){const date=dayKey(new Date(this.month.getFullYear(),this.month.getMonth(),d));const button=this.actionButton(String(d),'date',new Date(`${date}T12:00:00`).toLocaleDateString('ru-RU',{day:'numeric',month:'long',year:'numeric'}));button.dataset.date=date;button.className='calendar-day';button.classList.toggle('today',date===dayKey());button.classList.toggle('chosen',date===this.store.selectedDate);button.setAttribute('aria-pressed',String(date===this.store.selectedDate));if(this.store.data.schedule.some(s=>s.date===date))button.classList.add('has-event');grid.append(button);}const foot=this.element('div','calendar-foot');foot.append(this.element('span','','● Есть планы'),this.actionButton('Сегодня','today'));this.content.replaceChildren(header,weekdays,grid,foot);}
  action(action,button){if(action==='date'){this.store.selectDate(button.dataset.date);this.dashboard.navigate('plan');}if(action==='today'){this.month=new Date();this.month.setDate(1);this.store.selectDate(dayKey());this.update();}if(action==='previous'||action==='next'){this.month.setMonth(this.month.getMonth()+(action==='next'?1:-1));this.update();}}
}
